package mz.uem.restaurante.ui;
import java.awt.*; import javax.swing.*; import javax.swing.table.DefaultTableModel;
public class PainelFornecedores extends JPanel {
 private final DefaultTableModel modelo=new DefaultTableModel(new Object[]{"ID","Fornecedor","Telefone","E-mail","Estado"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable tabela=new JTable(modelo); private final JTextField pesquisa=new JTextField(18);
 public PainelFornecedores(){setLayout(new BorderLayout(0,14));setBorder(BorderFactory.createEmptyBorder(20,24,20,24));JPanel topo=new JPanel(new BorderLayout(8,8));topo.setOpaque(false);topo.add(Ui.titulo("Fornecedores"),BorderLayout.WEST);topo.add(pesquisa,BorderLayout.EAST);Ui.prepararTabela(tabela);JScrollPane scroll=new JScrollPane(tabela);Ui.card(scroll);JPanel acoes=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));acoes.setOpaque(false);JButton novo=Ui.botao("Novo fornecedor",Ui.DESTAQUE), editar=Ui.botaoSecundario("Editar"), remover=Ui.botao("Remover",Ui.ALERTA);acoes.add(novo);acoes.add(editar);acoes.add(remover);novo.addActionListener(e->formulario(-1));editar.addActionListener(e->formulario(tabela.getSelectedRow()));remover.addActionListener(e->{int r=tabela.getSelectedRow();if(r>=0)modelo.removeRow(r);});add(topo,BorderLayout.NORTH);add(scroll,BorderLayout.CENTER);add(acoes,BorderLayout.SOUTH);}
 private void formulario(int linha){JTextField n=new JTextField(),t=new JTextField(),e=new JTextField();JPanel p=new JPanel(new GridLayout(3,2,8,8));p.add(new JLabel("Nome:"));p.add(n);p.add(new JLabel("Telefone:"));p.add(t);p.add(new JLabel("E-mail:"));p.add(e);if(JOptionPane.showConfirmDialog(this,p,linha<0?"Novo fornecedor":"Editar fornecedor",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){if(linha<0)modelo.addRow(new Object[]{modelo.getRowCount()+1,n.getText(),t.getText(),e.getText(),"Activo"});else{modelo.setValueAt(n.getText(),linha,1);modelo.setValueAt(t.getText(),linha,2);modelo.setValueAt(e.getText(),linha,3);}}}
}
